                "question": "Concernant la cinétique enzymatique dans le modèle de Michaelis et Menten, la-quelle (lesquelles) des propositions suivantes est (sont) exacte(s) ?",
                "options": [
                    {
                        "id": "A",
                        "text": "Les enzymes catalysent les réactions en modifiant leur équilibre",
                        "isCorrect": false,
                        "explanation": "FAUX - → Les enzymes catalysent les réactions en modifiant leur équilibreC'est important à retenir : les enzymes ont un rôle cinétique en accélérant la vitesse d'atteinte de l'équilibre, mais la position de l'équilibre n'est pas déplacée."
                    },
                    {
                        "id": "B",
                        "text": "Dans la courbe primaire, la vitesse initiale de réaction n'est pas proportionnelle à la concen-tration initiale de substrat",
                        "isCorrect": true,
                        "explanation": "VRAI - → Dans la courbe primaire, la vitesse initiale de réaction n'est pas proportionnelle à …Ouiii la négation peut dérouter mais c'est exact.Petit topo sur la courbe primaire : elle modélise la vitesse d'apparition du produit [P] de la réaction enzymatique, sa fonction est [P]=f(t).On y distingue 3 phases de la réaction :La pré-stationnaire, tellement rapide qu'elle est négligeable. La concentration de complexes ES (enzyme-substrat) augmente très vite, on forme peu de produit.Ensuite, pendant la phase stationnaire, la concentration de complexes ES est stable, c'est l'état de croisière de la réaction. La portion de courbe est une droite, on a donc [P] qui augmente proportionnellement au temps. vi est alors la pente de la droite pour [S]0 fixée ; la relation entre vi et [S]0 n'apparaît que sur la courbe secondaire (vi=f([S]0), qui n'est pas une droite.Enfin, durant la dernière phase la réaction retour intervient, on est à l'équilibre."
                    },
                    {
                        "id": "C",
                        "text": "La Km est inversement proportionnelle à l'affinité de l'enzyme pour son substrat",
                        "isCorrect": false,
                        "explanation": "FAUX - → La Km est inversement proportionnelle à l'affinité de l'enzyme pour son substrat C'est exactement ça mais QUE dans l'hypothèse du quasi-équilibre, Km est le rapport de deux constantes de vitesse, celle de dissociation k−1 et celle d'association k1 du complexe enzyme-substrat. Plus k1 est supérieure à k−1, plus l'enzyme a une forte affinité à son substrat, plus le rapport inverse des deux, donc Km, sera petit."
                    },
                    {
                        "id": "D",
                        "text": "Sur la courbe de saturation, Km est la concentration de substrat pour laquelle on atteint la moitié de la Vmax",
                        "isCorrect": true,
                        "explanation": "VRAI - → Sur la courbe de saturation, Km est la concentration de substrat pour laquelle on …C'est THE méthode pour déterminer Km facilement en présence d'une courbe secondaire."
                    },
                    {
                        "id": "E",
                        "text": "Le plateau de la courbe secondaire correspond à l'équilibre de la réaction",
                        "isCorrect": false,
                        "explanation": "FAUX - → Le plateau de la courbe secondaire correspond à l'équilibre de la réactionAïe le plateau représente bien l'équilibre de réaction, mais pour la courbe primaire ! Concernant la courbe secondaire, le plateau est visible à saturation des enzymes par le substrat, c'est d'ailleurs pour ça qu'on l'appelle aussi courbe de saturation. Pratiquement tous les sites actifs sont occupés, donc augmenter davantage [S] n'augmente presque plus la vitesse."
                    }
                ],
