                        "explanation": "VRAI - → La combustion d'une mole de glucose consomme 6 moles de dioxygèneMAIS OUI MAIS NON MAIS OUI (vrai) La réaction de combustion complète du glucose s'écrit :C6H12O6(s) + 6 O<sub>2</sub>(g) −−→ 6 CO<sub>2</sub>(g) + 6 H<sub>2</sub>O(l)Une mole de glucose nécessite donc 6 moles de dioxygène.Items B et CCalculons l'enthalpie standard de réaction :∆ H =∆r◦ΣfH (produits) −∆◦ΣfH (réactifs)◦∆rH◦ = [6 × (−393) + 6 × (−286)] − [−1274 + 6 × (0)] = −2800 kJ · mol−1La combustion est exothermique (∆rH◦ < 0). En augmentant la température du milieu réaction-nel, le système va chercher à s'opposer à cette perturbation. Il va donc favoriser le sens qui permet de consommer la chaleur apportée. Or, le sens qui consomme de la chaleur est le sens endother-mique. Mais notre réaction directe est exothermique. Donc son sens inverse est nécessairement endothermique.Ainsi, l'augmentation de température ne favorise pas la formation des produits de la combustion."
